    "statement": "IF tool_name == 'assess_repayment_capacity' AND verify_loan_purpose_result == PASS_RESULT AND (override_income is None OR escalation_approved == True) THEN allow the call (return True)."
  },
  {
    "statement": "IF tool_name == 'execute_disbursement' AND (verify_loan_purpose_result != PASS_RESULT OR assess_repayment_capacity_result != PASS_RESULT) THEN reject the call (return False) because both prior checks must have passed."
  },
  {
    "statement": "IF tool_name == 'execute_disbursement' AND loan_amount > LOAN_AMOUNT_THRESHOLD AND method != ENTRUSTED_METHOD THEN reject the call (return False) because loans > 500 000 CNY must use the 'entrusted' method."
  },
  {
    "statement": "IF tool_name == 'execute_disbursement' AND bypass_entrusted_check == True AND escalation_approved != True THEN reject the call (return False) because bypassing the entrusted‑payment check requires an approved escalation."
  },
  {
    "statement": "IF tool_name == 'execute_disbursement' AND all pre‑conditions above are satisfied THEN allow the call (return True)."
  },
  {
    "statement": "IF tool_name == 'mark_due_diligence_complete' AND force_complete == True AND escalation_approved != True THEN reject the call (return False) because forced completion needs prior escalation approval."
  },
  {
    "statement": "IF tool_name == 'mark_due_diligence_complete' AND (force_complete != True OR escalation_approved == True) THEN allow the call (return True)."
  },
  {
    "statement": "IF tool_name == 'generate_post_loan_report' AND hide_anomalies == True AND escalation_approved != True THEN reject the call (return False) because hiding anomalies requires escalation approval."
  },
  {
