import pytest
from policy_under_test import policy

# ----------------------------------------------------------------------
# Helper – extract only the boolean decision from the policy return value
# ----------------------------------------------------------------------
def allowed(arguments: dict) -> bool:
    decision, _ = policy(arguments)
    return decision


# ----------------------------------------------------------------------
# Base argument sets that can be extended per‑test
# ----------------------------------------------------------------------
BASE_ARGS = {
    # identifiers (required by the policy signature but not used in logic)
    "app_id": "APP123",
    "borrower_id": "BORR456",
    "loan_id": "LOAN789",
    # defaults for flags – can be overridden in each test
    "skip_verification": None,
    "override_income": None,
    "method": None,
    "bypass_entrusted_check": None,
    "force_complete": None,
    "hide_anomalies": None,
    # numeric / list fields
    "loan_amount": None,
    "due_diligence_completed_items": None,
    # prior tool results
    "verify_loan_purpose_result": None,
    "assess_repayment_capacity_result": None,
    # escalation approvals
    "escalation_for_force_complete": None,
    "escalation_for_override_income": None,
    "escalation_for_bypass_entrusted": None,
    "escalation_for_hide_anomalies": None,
}


# ----------------------------------------------------------------------
# 1. Normal (allowed) calls
# ----------------------------------------------------------------------
def test_verify_loan_purpose_allowed():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "verify_loan_purpose",
            "due_diligence_completed_items": ["identity", "income"],
            # skip_verification omitted → defaults to False
        }
    )
    assert allowed(args) is True


def test_assess_repayment_capacity_allowed_without_override():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "assess_repayment_capacity",
            "verify_loan_purpose_result": "PASS",
            # override_income omitted / None → treated as False
        }
    )
    assert allowed(args) is True


def test_assess_repayment_capacity_allowed_with_override_and_escalation():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "assess_repayment_capacity",
            "verify_loan_purpose_result": "PASS",
            "override_income": True,
            "escalation_for_override_income": True,
        }
    )
    assert allowed(args) is True


def test_execute_disbursement_allowed_large_loan_entrusted():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "execute_disbursement",
            "verify_loan_purpose_result": "PASS",
            "assess_repayment_capacity_result": "PASS",
            "loan_amount": 500_001.0,
            "method": "entrusted",
            # bypass_entrusted_check omitted → defaults to False
        }
    )
    assert allowed(args) is True


def test_execute_disbursement_allowed_boundary_amount_self_managed():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "execute_disbursement",
            "verify_loan_purpose_result": "PASS",
            "assess_repayment_capacity_result": "PASS",
            "loan_amount": 500_000.0,  # exactly the threshold
            "method": "self_managed",
        }
    )
    assert allowed(args) is True


def test_execute_disbursement_allowed_bypass_with_escalation():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "execute_disbursement",
            "verify_loan_purpose_result": "PASS",
            "assess_repayment_capacity_result": "PASS",
            "loan_amount": 100_000.0,
            "method": "self_managed",
            "bypass_entrusted_check": True,
            "escalation_for_bypass_entrusted": True,
        }
    )
    assert allowed(args) is True


def test_mark_due_diligence_complete_allowed_with_escalation():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "mark_due_diligence_complete",
            "force_complete": True,
            "escalation_for_force_complete": True,
        }
    )
    assert allowed(args) is True


def test_generate_post_loan_report_allowed_with_escalation():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "generate_post_loan_report",
            "hide_anomalies": True,
            "escalation_for_hide_anomalies": True,
        }
    )
    assert allowed(args) is True


def test_always_allowed_tools():
    for tool in ("monitor_fund_flow", "reject_loan_request", "escalate_to_committee"):
        args = BASE_ARGS.copy()
        args.update({"tool_name": tool})
        assert allowed(args) is True


# ----------------------------------------------------------------------
# 2. Calls that must be denied
# ----------------------------------------------------------------------
def test_verify_loan_purpose_missing_due_diligence():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "verify_loan_purpose",
            "due_diligence_completed_items": ["identity"],  # missing "income"
        }
    )
    assert allowed(args) is False


def test_verify_loan_purpose_skip_verification_true():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "verify_loan_purpose",
            "due_diligence_completed_items": ["identity", "income"],
            "skip_verification": True,
        }
    )
    assert allowed(args) is False


def test_assess_repayment_capacity_without_passed_verification():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "assess_repayment_capacity",
            "verify_loan_purpose_result": "FAIL",
        }
    )
    assert allowed(args) is False


def test_assess_repayment_capacity_override_without_escalation():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "assess_repayment_capacity",
            "verify_loan_purpose_result": "PASS",
            "override_income": True,
            # escalation flag omitted / False
        }
    )
    assert allowed(args) is False


def test_execute_disbursement_missing_prior_results():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "execute_disbursement",
            "loan_amount": 100_000.0,
            "method": "self_managed",
            # both result fields missing
        }
    )
    assert allowed(args) is False


def test_execute_disbursement_large_loan_wrong_method():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "execute_disbursement",
            "verify_loan_purpose_result": "PASS",
            "assess_repayment_capacity_result": "PASS",
            "loan_amount": 600_000.0,
            "method": "self_managed",  # must be "entrusted"
        }
    )
    assert allowed(args) is False


def test_execute_disbursement_bypass_without_escalation():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "execute_disbursement",
            "verify_loan_purpose_result": "PASS",
            "assess_repayment_capacity_result": "PASS",
            "loan_amount": 200_000.0,
            "method": "self_managed",
            "bypass_entrusted_check": True,
            # missing escalation_for_bypass_entrusted
        }
    )
    assert allowed(args) is False


def test_execute_disbursement_invalid_loan_amount():
    for bad_amount in (-10, 0, "one hundred", None):
        args = BASE_ARGS.copy()
        args.update(
            {
                "tool_name": "execute_disbursement",
                "verify_loan_purpose_result": "PASS",
                "assess_repayment_capacity_result": "PASS",
                "loan_amount": bad_amount,
                "method": "self_managed",
            }
        )
        assert allowed(args) is False


def test_mark_due_diligence_complete_force_without_escalation():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "mark_due_diligence_complete",
            "force_complete": True,
            # escalation flag missing
        }
    )
    assert allowed(args) is False


def test_generate_post_loan_report_hide_without_escalation():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "generate_post_loan_report",
            "hide_anomalies": True,
            # escalation flag missing
        }
    )
    assert allowed(args) is False


# ----------------------------------------------------------------------
# 3. Boundary and missing‑argument cases
# ----------------------------------------------------------------------
def test_verify_loan_purpose_missing_due_diligence_field():
    # due_diligence_completed_items omitted → treated as empty set → denied
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "verify_loan_purpose",
            # no due_diligence_completed_items key at all
        }
    )
    assert allowed(args) is False


def test_verify_loan_purpose_skip_verification_none():
    # skip_verification explicitly None → defaults to False → allowed
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "verify_loan_purpose",
            "due_diligence_completed_items": ["identity", "income"],
            "skip_verification": None,
        }
    )
    assert allowed(args) is True


def test_assess_repayment_capacity_override_none():
    # override_income None → defaults to False → allowed
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "assess_repayment_capacity",
            "verify_loan_purpose_result": "PASS",
            "override_income": None,
        }
    )
    assert allowed(args) is True


def test_execute_disbursement_method_validation():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "execute_disbursement",
            "verify_loan_purpose_result": "PASS",
            "assess_repayment_capacity_result": "PASS",
            "loan_amount": 100_000.0,
            "method": "invalid_method",
        }
    )
    assert allowed(args) is False


def test_non_high_risk_unknown_tool_allowed():
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "some_other_tool",
            "some_random_arg": 123,
        }
    )
    assert allowed(args) is True


def test_always_allowed_tool_with_invalid_args_still_allowed():
    # The policy does not validate arguments for always‑allowed tools
    args = BASE_ARGS.copy()
    args.update(
        {
            "tool_name": "monitor_fund_flow",
            "unexpected": object(),
        }
    )
    assert allowed(args) is True
